  var other=new Principal(new SubjectId("history-other"),f.p.tenantId(),f.p.permissions(),f.p.resourceScope());check(api.history(other,ref.id(),1,null).recordedCount()==0);fail(WorkflowFailure.Code.NOT_FOUND,()->api.history(other,ref.id(),1,first.nextCursor()));var denied=new Principal(f.p.subjectId(),f.p.tenantId(),Set.of(Permission.SOURCE_SYNC),f.p.resourceScope());fail(WorkflowFailure.Code.FORBIDDEN,()->api.history(denied,ref.id(),1,first.nextCursor()));var foreign=new Principal(f.p.subjectId(),new TenantId("history-foreign"),f.p.permissions(),f.p.resourceScope());fail(WorkflowFailure.Code.NOT_FOUND,()->api.history(foreign,ref.id(),1,null));fail(WorkflowFailure.Code.NOT_FOUND,()->api.history(f.p,ref.id(),2,null));fail(WorkflowFailure.Code.NOT_FOUND,()->api.history(f.p,ref.id(),1,"h1.unknown"));invalid(()->api.history(f.p,ref.id(),1,"h1.padded=="));
