  invalid(()->new Cursor("2.0",at,0,45,20,UUID.randomUUID()));invalid(()->new Cursor("2.0",at,45,45,21,UUID.randomUUID()));invalid(()->new Cursor("2.0",at,45,20,20,UUID.randomUUID()));invalid(()->new Page("2.0",at,at,ref,"ALL_RUNS",0,0,List.of(),null,false));invalid(()->new Page("2.0",at,at,ref,"RECORDED_CHECKS",20,20,List.of(),null,false));invalid(()->new Page("2.0",at,at,ref,"RECORDED_CHECKS",0,45,first.items(),null,true));var reversed=new ArrayList<>(first.items());Collections.reverse(reversed);invalid(()->new Page("2.0",at,at,ref,"RECORDED_CHECKS",0,45,reversed,"h1.fixture",true));
  var capacity=new WorkflowLogStreamSmoke.Fixture();var cr=new WorkflowQuality.Reference(capacity.d.id(),1,capacity.d.digest());var tied=new ArrayList<WorkflowDiagnostics.Observation>();for(int i=0;i<200;i++)tied.add(WorkflowQualityAlertsSmoke.observation(cr,capacity.clock.instant(),true,null));capacity.store.transaction(capacity.p.tenantId(),s->{tied.forEach(o->s.addDiagnostic(capacity.p.subjectId().value(),new WorkflowDiagnostics.Stored(o,List.of())));return null;});tied.sort(WorkflowHistory.ORDER);var bounded=new WorkflowHistoryService(capacity.store,capacity.flows,new SyntheticCursors(),capacity.clock);var all=new ArrayList<WorkflowDiagnostics.Observation>();String token=null;for(int i=0;i<10;i++){var p=bounded.history(capacity.p,cr.id(),1,token);check(p.offset()==i*20&&p.recordedCount()==200&&p.items().size()==20);all.addAll(p.items());token=p.nextCursor();}check(token==null&&all.equals(tied)&&all.stream().map(WorkflowDiagnostics.Observation::id).distinct().count()==200);checks++;try{capacity.store.transaction(capacity.p.tenantId(),s->{s.addDiagnostic(capacity.p.subjectId().value(),new WorkflowDiagnostics.Stored(WorkflowQualityAlertsSmoke.observation(cr,capacity.clock.instant(),true,null),List.of()));return null;});throw new AssertionError();}catch(IllegalStateException expected){}check(capacity.reads==0&&capacity.sink.writes==0);

